"""Application controller — owns root window, coordinates components."""

from __future__ import annotations

import logging
import os
import subprocess
import sys
import threading
import tkinter as tk

from personal_assistant.claude_client import send_prompt
from personal_assistant.main_window import MainWindow

logger = logging.getLogger(__name__)

# Voice script location — reuses the voice skill infrastructure
_VOICE_SCRIPT = os.path.expanduser("~/.claude/skills/voice/scripts/voice.py")
_VOICE_PYTHON = os.path.expanduser("~/.claude/venvs/voice/bin/python")
if sys.platform == "win32":
    _VOICE_PYTHON = os.path.expanduser("~/.claude/venvs/voice/Scripts/python.exe")

_VOICE_DEBUG_LOG = os.path.expanduser("~/.config/claude-skill-voice/debug.log")


class AppController:
    """Single controller coordinating the application lifecycle."""

    def __init__(self, *, debug: bool = False):
        self._root = tk.Tk()
        self._root.withdraw()  # Hidden — not used as a visible window
        self._debug = debug
        self._conversation_started = False

        self._main_window = MainWindow(self._root, self)

    def run(self) -> None:
        """Enter the mainloop."""
        self._root.mainloop()

    def quit(self) -> None:
        """Clean shutdown."""
        self._root.quit()

    def send_prompt(self, prompt: str) -> None:
        """Send a prompt to Claude in a background thread."""
        thread = threading.Thread(
            target=self._run_prompt,
            args=(prompt,),
            daemon=True,
            name="claude-prompt",
        )
        thread.start()

    def _run_prompt(self, prompt: str) -> None:
        """Background thread — runs claude -p and dispatches result to main thread."""
        response = send_prompt(prompt, continue_conversation=self._conversation_started)
        self._conversation_started = True
        self._root.after(0, self._main_window.append_response, response)

    def start_voice(self) -> None:
        """Launch voice recording in a background thread."""
        if not os.path.exists(_VOICE_SCRIPT):
            self._root.after(
                0,
                self._main_window.append_response,
                "[error] voice script not found at " + _VOICE_SCRIPT,
            )
            return

        thread = threading.Thread(
            target=self._run_voice,
            daemon=True,
            name="voice-record",
        )
        thread.start()

    def _run_voice(self) -> None:
        """Background: record voice, parse transcript, send to Claude."""
        cmd = [
            _VOICE_PYTHON,
            _VOICE_SCRIPT,
            "--stream",
            "--debug",
            _VOICE_DEBUG_LOG,
        ]
        logger.debug("running voice: %s", cmd)
        try:
            result = subprocess.run(cmd, capture_output=True, text=True, timeout=600)
        except subprocess.TimeoutExpired:
            self._root.after(
                0,
                self._main_window.append_response,
                "[error] voice recording timed out",
            )
            return
        except Exception as e:
            self._root.after(
                0,
                self._main_window.append_response,
                f"[error] voice failed: {e}",
            )
            return

        stdout = result.stdout
        if "[CANCEL]" in stdout:
            self._root.after(
                0,
                self._main_window._set_status,
                "Ready",
            )
            return

        # Parse transcript between [BEGIN ...] and [END]
        lines = stdout.splitlines()
        transcript_lines = []
        in_transcript = False
        for line in lines:
            if line.startswith("[BEGIN"):
                in_transcript = True
                continue
            if line == "[END]":
                in_transcript = False
                continue
            if in_transcript:
                transcript_lines.append(line)

        transcript = "\n".join(transcript_lines).strip()
        if not transcript:
            self._root.after(
                0,
                self._main_window.append_response,
                "[no speech detected — try again]",
            )
            return

        # Show the transcript as user input, then send to Claude
        self._root.after(0, self._main_window.append_user_input, transcript)
        self._root.after(0, self._main_window._set_status, "Thinking...")
        self._run_prompt(transcript)
